import { useEffect, useState } from "react";
import Papa from "papaparse";
import { haversine, getWaterRisk, AREA_NOISE_LEVEL, DISEASE_POLLUTANTS } from "./constants.js";

let _cachedHouses = null;
let _areaCoordsCache = null;

// ── Load OSM-geocoded area coordinates (generated by geocode_locations.py) ───
async function loadAreaCoords() {
  if (_areaCoordsCache) return _areaCoordsCache;
  try {
    const res = await fetch("/areaCoords.json?v=1");
    if (res.ok) {
      _areaCoordsCache = await res.json();
      return _areaCoordsCache;
    }
  } catch (_) {}
  _areaCoordsCache = {};
  return _areaCoordsCache;
}

/**
 * Given a house location string and its raw CSV lat/lng, return the best
 * available coordinates:
 *   1. Exact match in OSM-geocoded areaCoords.json  (most accurate)
 *   2. Partial match in areaCoords.json
 *   3. Fallback centroid table (covers ~30 major areas)
 *   4. Raw CSV coordinates as last resort
 *
 * A small deterministic jitter (±300 m) is added so houses in the same
 * area don't all stack on one pin.
 */
function resolveCoords(loc, rawLat, rawLng, rowIndex, areaCoords) {
  const locTrimmed = loc.trim();
  const locLower   = locTrimmed.toLowerCase();

  // 1. Exact match
  if (areaCoords[locTrimmed]) {
    const { lat, lng } = areaCoords[locTrimmed];
    return applyJitter(lat, lng, rowIndex);
  }

  // 2. Partial match — find the longest key that is a substring of loc
  let bestKey = null, bestLen = 0;
  for (const key of Object.keys(areaCoords)) {
    const kl = key.toLowerCase();
    if (locLower.includes(kl) && kl.length > bestLen) {
      bestKey = key; bestLen = kl.length;
    }
  }
  if (bestKey) {
    const { lat, lng } = areaCoords[bestKey];
    return applyJitter(lat, lng, rowIndex);
  }

  // 3. Hardcoded fallback centroids for the most common mis-geocoded areas
  const FALLBACK = {
    "sarjapur":        { lat: 12.8700, lng: 77.7400 },
    "whitefield":      { lat: 12.9698, lng: 77.7499 },
    "electronic city": { lat: 12.8446, lng: 77.6616 },
    "marathahalli":    { lat: 12.9591, lng: 77.6974 },
    "bellandur":       { lat: 12.9343, lng: 77.6687 },
    "hsr layout":      { lat: 12.9081, lng: 77.6476 },
    "koramangala":     { lat: 12.9352, lng: 77.6245 },
    "indiranagar":     { lat: 12.9784, lng: 77.6408 },
    "hebbal":          { lat: 13.0358, lng: 77.5970 },
    "yelahanka":       { lat: 13.1007, lng: 77.5963 },
    "jayanagar":       { lat: 12.9250, lng: 77.5938 },
    "jp nagar":        { lat: 12.9063, lng: 77.5857 },
    "banashankari":    { lat: 12.9241, lng: 77.5540 },
    "varthur":         { lat: 12.9354, lng: 77.7355 },
    "kr puram":        { lat: 13.0050, lng: 77.6960 },
    "peenya":          { lat: 13.0280, lng: 77.5190 },
    "yeshwanthpur":    { lat: 13.0270, lng: 77.5490 },
    "malleshwaram":    { lat: 13.0035, lng: 77.5710 },
    "rajaji nagar":    { lat: 12.9916, lng: 77.5530 },
    "bannerghatta":    { lat: 12.8630, lng: 77.5970 },
    "devanahalli":     { lat: 13.2490, lng: 77.7120 },
    "thanisandra":     { lat: 13.0530, lng: 77.6380 },
    "hennur":          { lat: 13.0430, lng: 77.6380 },
    "bommanahalli":    { lat: 12.8960, lng: 77.6270 },
    "mysore road":     { lat: 12.9540, lng: 77.5100 },
    "tumkur road":     { lat: 13.0500, lng: 77.5100 },
    "vijayanagar":     { lat: 12.9710, lng: 77.5350 },
    "kanakpura":       { lat: 12.9050, lng: 77.5480 },
  };
  for (const [key, centroid] of Object.entries(FALLBACK)) {
    if (locLower.includes(key)) {
      return applyJitter(centroid.lat, centroid.lng, rowIndex);
    }
  }

  // 4. Raw CSV coords — only use if they look valid and not a known bad anchor
  const BAD_ANCHORS = [
    [12.8258, 77.7849], // Wipro campus (used for all Sarjapur entries)
  ];
  const isBadAnchor = BAD_ANCHORS.some(
    ([blat, blng]) => Math.abs(rawLat - blat) < 0.001 && Math.abs(rawLng - blng) < 0.001
  );
  if (!isBadAnchor && rawLat > 12.7 && rawLat < 13.2) {
    return applyJitter(rawLat, rawLng, rowIndex);
  }

  // Last resort: Bangalore city centre
  return applyJitter(12.9716, 77.5946, rowIndex);
}

function applyJitter(lat, lng, rowIndex) {
  // ±0.003° ≈ ±300 m — enough to spread pins, small enough to stay in the area
  const jLat = ((rowIndex * 7  + 3) % 61 - 30) * 0.0001;
  const jLng = ((rowIndex * 13 + 5) % 61 - 30) * 0.0001;
  return { lat: lat + jLat, lng: lng + jLng };
}

export function useHouses() {
  const [houses, setHouses]   = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (_cachedHouses) { setHouses(_cachedHouses); setLoading(false); return; }

    // Load OSM coords and CSV in parallel
    Promise.all([
      loadAreaCoords(),
      new Promise(resolve => {
        Papa.parse("/houses_geocoded.csv?v=" + Date.now(), {
          download: true, header: true, dynamicTyping: true,
          complete: r => resolve(r.data),
        });
      }),
    ]).then(([areaCoords, rows]) => {
      const valid = rows.map((row, i) => {
        const rawLat = parseFloat(row.lat || row.latitude || 0);
        const rawLng = parseFloat(row.lng || row.longitude || 0);
        const loc    = String(row.location || "").trim();
        const { lat, lng } = resolveCoords(loc, rawLat, rawLng, i, areaCoords);
        const amenities = deriveAmenities(row);

        return {
          id: i,
          loc,
          bhk:          parseInt(row.bhk || 0),
          sqft:         parseFloat(row.total_sqft || 0),
          bath:         parseInt(row.bath || 0),
          balcony:      parseInt(row.balcony || 0),
          price:        parseFloat(row.price || 0),
          lat,
          lng,
          soc:          String(row.society || "").trim(),
          areaType:     String(row.area_type || "").trim(),
          availability: String(row.availability || "").trim(),
          amenities,
        };
      }).filter(h =>
        isFinite(h.lat) && isFinite(h.lng) &&
        h.lat > 12.7 && h.lat < 13.2 && h.lng > 77.3 && h.lng < 77.9 &&
        h.price > 0 && h.bhk > 0
      );

      _cachedHouses = valid;
      setHouses(valid);
      setLoading(false);
    });
  }, []);

  return { houses, loading };
}

/**
 * Derive likely amenities from CSV fields (area_type, society name, balcony, bath count).
 * The CSV doesn't have an amenities column, so we infer from available signals.
 */
function deriveAmenities(row) {
  const amenities = [];
  const areaType  = String(row.area_type || "").toLowerCase();
  const society   = String(row.society || "").toLowerCase();
  const bath      = parseInt(row.bath || 0);
  const balcony   = parseInt(row.balcony || 0);
  const sqft      = parseFloat(row.total_sqft || 0);
  const price     = parseFloat(row.price || 0);

  // Super built-up area → typically has lift, security, power backup
  if (areaType.includes("super built")) {
    amenities.push("Lift", "Security", "Power Backup");
  }

  // Society name present → gated community features
  if (society && society.length > 2) {
    amenities.push("Security");
    if (sqft > 1200) amenities.push("Parking");
  }

  // Balcony present
  if (balcony > 0) amenities.push("Balcony");

  // Multiple bathrooms → likely semi/fully furnished
  if (bath >= 3) amenities.push("AC");

  // Large sqft → likely has parking
  if (sqft > 1500) {
    if (!amenities.includes("Parking")) amenities.push("Parking");
  }

  // High price → premium amenities
  if (price > 100) {
    amenities.push("Gym", "Swimming Pool");
    if (!amenities.includes("AC")) amenities.push("AC");
  } else if (price > 60) {
    if (!amenities.includes("AC")) amenities.push("AC");
    amenities.push("Garden");
  }

  // Ready to move → water supply confirmed
  if (String(row.availability || "").toLowerCase().includes("ready")) {
    amenities.push("Water Supply");
  }

  // Deduplicate
  return [...new Set(amenities)];
}

// ── Static AQI per area (fallback when no WAQI token) ────────────────────────
// Based on CPCB / IQAir historical data for Bengaluru areas
const AREA_STATIC_AQI = {
  // Low AQI (Good / Moderate) — safe for sensitive groups
  "Yelahanka":              42,
  "Devanahalli":            45,
  "Kanakpura Road":         48,
  "Banashankari":           50,
  "Jayanagar":              52,
  "Jp Nagar":               53,
  "Bannerghatta Road":      54,
  "Electronic City":        58,
  "Electronics City Phase 1": 58,
  "Electronic City Phase Ii": 58,
  "Koramangala":            62,
  "Whitefield":             65,
  "Hsr Layout":             65,
  "Hebbal Kempapura":       68,
  "Thanisandra":            68,
  "Hennur Road":            70,
  "Bellandur":              72,
  // Medium AQI (Moderate / Unhealthy for Sensitive)
  "Indiranagar":            75,
  "Sarjapur Road":          78,
  "Hebbal":                 80,
  "Rajaji Nagar":           85,
  "Malleshwaram":           88,
  "Vijayanagar":            90,
  "Hosur Road":             92,
  "Bommanahalli":           95,
  "Marathahalli":           105,
  "Mysore Road":            108,
  // High AQI — avoid for health conditions
  "Kr Puram":               125,
  "Old Madras Road":        130,
  "Yeshwanthpur":           140,
  "Magadi Road":            145,
  "Tumkur Road":            150,
  "Peenya":                 165,
  "Bommasandra Industrial Area": 170,
};

/**
 * Get static AQI for a location string (partial match).
 * Returns a synthetic aqiData object compatible with computeHealthPenalty.
 */
export function getStaticAqi(loc) {
  if (!loc) return { aqi: 80, live: false, iaqi: {} };
  const locLower = loc.toLowerCase();
  for (const [area, aqi] of Object.entries(AREA_STATIC_AQI)) {
    if (locLower.includes(area.toLowerCase())) return { aqi, live: false, iaqi: {} };
  }
  return { aqi: 80, live: false, iaqi: {} };
}

/**
 * Get static noise dB for a location string.
 */
function getStaticNoise(loc) {
  if (!loc) return 60;
  const locLower = loc.toLowerCase();
  for (const [area, data] of Object.entries(AREA_NOISE_LEVEL)) {
    if (locLower.includes(area.toLowerCase())) return data.db;
  }
  return 60;
}

/**
 * Compute a static health penalty (0–1) using only area-level data.
 * Used during candidate retrieval before WAQI data is available.
 * For health conditions, AQI is the primary signal.
 */
function staticHealthPenalty(loc, conditions) {
  if (!conditions || conditions.length === 0) return 0;

  const aqiData  = getStaticAqi(loc);
  const noiseDb  = getStaticNoise(loc);
  const waterData = getWaterRisk(loc);

  let totalPenalty = 0;

  for (const cond of conditions) {
    const mapping = DISEASE_POLLUTANTS[cond];
    if (!mapping) continue;

    let p = 0;

    // AQI penalty — primary signal, weighted heavily for air-sensitive conditions
    if (aqiData.aqi > mapping.aqiLimit) {
      // Linear scale: exceeding limit by 50% → 0.5 penalty, capped at 0.7
      p += Math.min(0.7, ((aqiData.aqi - mapping.aqiLimit) / mapping.aqiLimit) * 0.7);
    }

    // Water penalty
    if (mapping.water.length > 0) {
      const issues = (waterData.issues || []).map(i => i.toLowerCase());
      const hits = mapping.water.filter(w => issues.some(i => i.includes(w)));
      if (hits.length > 0) p += waterData.risk === "HIGH" ? 0.35 : 0.15;
    }

    // Noise penalty
    if (noiseDb > mapping.noiseLimit) {
      p += Math.min(0.2, ((noiseDb - mapping.noiseLimit) / mapping.noiseLimit) * 0.2);
    }

    totalPenalty += p;
  }

  return Math.min(0.95, totalPenalty / conditions.length);
}

/**
 * Retrieve and rank candidates with health-aware scoring.
 *
 * Algorithm:
 * 1. Apply hard filters (budget, BHK, area keyword)
 * 2. Compute distance to workplace for every house using corrected coordinates
 * 3. Compute static health penalty for every house using area AQI/noise/water
 * 4. Combined score = distanceScore × (1 - healthPenalty)
 *    — when health conditions exist, healthPenalty dominates for unsafe areas
 * 5. De-duplicate by location name (not lat/lng bucket) to avoid repeats
 * 6. Return top N with AQI and amenity data attached
 */
export function retrieveCandidates(houses, prefs, companyCoords, topN = 20, conditions = []) {
  const { budgetMin, budgetMax, bhkList, areaKeyword } = prefs;

  // Step 1: hard filters
  let filtered = houses.filter(h => {
    if (budgetMin && h.price < budgetMin) return false;
    if (budgetMax && h.price > budgetMax) return false;
    if (bhkList && bhkList.length > 0) {
      const bv = h.bhk >= 5 ? 5 : h.bhk;
      if (!bhkList.includes(bv)) return false;
    }
    if (areaKeyword) {
      const kw = areaKeyword.toLowerCase();
      if (!h.loc.toLowerCase().includes(kw) && !(h.soc || "").toLowerCase().includes(kw)) return false;
    }
    return true;
  });

  // Relax area keyword if nothing found
  if (filtered.length === 0) {
    filtered = houses.filter(h => {
      if (budgetMin && h.price < budgetMin) return false;
      if (budgetMax && h.price > budgetMax) return false;
      if (bhkList && bhkList.length > 0) {
        const bv = h.bhk >= 5 ? 5 : h.bhk;
        if (!bhkList.includes(bv)) return false;
      }
      return true;
    });
  }

  // Relax budget too if still nothing
  if (filtered.length === 0) {
    filtered = houses.filter(h => {
      if (bhkList && bhkList.length > 0) {
        const bv = h.bhk >= 5 ? 5 : h.bhk;
        if (!bhkList.includes(bv)) return false;
      }
      return true;
    });
  }

  // Step 2 & 3: score every house
  const scored = filtered.map(h => {
    // Use haversine with corrected coordinates (already fixed during CSV load)
    const rawDist   = haversine(companyCoords.lat, companyCoords.lng, h.lat, h.lng);
    // Enforce a minimum realistic distance of 0.3 km to avoid 0-distance artefacts
    const dist      = Math.max(0.3, Math.round(rawDist * 10) / 10);
    const waterData = getWaterRisk(h.loc);
    const healthPen = staticHealthPenalty(h.loc, conditions);
    const distScore = 1 / (dist + 0.5); // +0.5 avoids extreme scores for very close houses
    // Attach static AQI data for display
    const aqiData   = getStaticAqi(h.loc);
    // When health conditions exist, health penalty is weighted 60%, distance 40%
    const finalScore = conditions.length > 0
      ? distScore * 0.4 * (1 - healthPen) + (1 - healthPen) * 0.6
      : distScore * (1 - (waterData.risk === "HIGH" ? 0.3 : waterData.risk === "MEDIUM" ? 0.15 : 0));
    return { ...h, dist, waterData, healthPen, finalScore, aqiData };
  });

  // Step 4: sort by final score descending
  scored.sort((a, b) => b.finalScore - a.finalScore);

  // Step 5: de-duplicate by location name — keep only the best-scored house per area
  const seenLoc = new Set();
  const unique  = [];
  for (const h of scored) {
    const locKey = h.loc.toLowerCase().trim();
    if (!seenLoc.has(locKey)) {
      seenLoc.add(locKey);
      unique.push(h);
    }
    if (unique.length >= topN) break;
  }

  return unique;
}
